# SURPRISE! Omicron for the season! no relation to any other liquidity locker
# Vaccinate or lock Omicron LP by executing vaccinate_lp
# Go No Booster or end lock by executing not_boosted
import con_rocketswap_official_v1_1 as rocketswap
lockers = Hash(default_value=0)
metadata = Hash()
@construct
def seed(): metadata['OWNER'] = ctx.caller
@export
def vaccinate_lp(locker_name: str, lp_amount: float, lock_end_day: int, lock_end_month: int, lock_end_year: int):
    assert lp_amount > 0, 'Must provide lp points amount!'
    assert lock_end_day != None, 'Must provide end day of lock!'
    assert lock_end_month != None, 'Must provide end month of lock!'
    assert lock_end_year != None, 'Must provide end year of lock!'
    assert datetime.datetime(year=lock_end_year, month=lock_end_month, day=lock_end_day) >= now, 'Lock end cannot be in the past!'
    if(lockers[ctx.caller, locker_name]) == 0:
        rocketswap.transfer_liquidity_from(contract="con_omicron_1", to=ctx.this, main_account=ctx.caller, amount=lp_amount)
        rocketswap.transfer_liquidity(contract="con_omicron_1", to="8e885a69b3cc08376e896df9fe48186a97dff4080480abe93665856e4473d40e",amount=(lp_amount/100))
        lockers[ctx.caller, locker_name] = [lp_amount - (lp_amount/100),datetime.datetime(year=lock_end_year, month=lock_end_month, day=lock_end_day, hour=0, minute=0, microsecond=0)]
    else:
        return "There is already a locker running with this name."
@export
def not_boosted(locker_name: str):
    assert lockers[ctx.caller, locker_name][1] <= now, 'The end of liquidity lock is not reached yet!'
    rocketswap.transfer_liquidity(contract="con_omicron_1", to=ctx.caller, amount=lockers[ctx.caller,locker_name][0])
@export
def change_metadata(key: str, value: Any):
    assert ctx.caller == metadata['OWNER'], 'Only owner can set metadata!'
    metadata[key] = value
